using System;
using Element.Services.Element.Core.Entities;
using Microsoft.EntityFrameworkCore;

namespace Element.Services.Element.Infrastructure.Persistence;

public class ElementDbContext : DbContext
{
    public ElementDbContext(DbContextOptions<ElementDbContext> options) : base(options)
    {
    }

    public DbSet<ChemicalElement> ChemicalElements => Set<ChemicalElement>();
    public DbSet<ElementPriceHistory> PriceHistories => Set<ElementPriceHistory>();
    public DbSet<ElementCategory> Categories => Set<ElementCategory>();
    public DbSet<StockReservation> StockReservations => Set<StockReservation>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        modelBuilder.Entity<ChemicalElement>(entity =>
        {
            entity.HasKey(e => e.Id);
            entity.HasQueryFilter(e => e.AtomicNumber >= 1 && e.AtomicNumber <= 118);
            entity.HasIndex(e => e.Symbol).IsUnique();
            entity.Property(e => e.Symbol).IsRequired().HasMaxLength(10);
            entity.Property(e => e.Name).IsRequired().HasMaxLength(100);
            entity.Property(e => e.NameTr).HasMaxLength(100);
            entity.Property(e => e.Category).IsRequired().HasMaxLength(100);
            entity.Property(e => e.Phase).IsRequired().HasMaxLength(50);
            entity.Property(e => e.Color).HasMaxLength(50);
            entity.Property(e => e.Block).HasMaxLength(2);
            entity.Property(e => e.Appearance).HasMaxLength(300);
            entity.Property(e => e.Uses).HasMaxLength(300);
            entity.Property(e => e.Summary).HasMaxLength(600);
            entity.Property(e => e.ImageUrl).HasMaxLength(500);
            entity.Property(e => e.SellerName).HasMaxLength(120);
            entity.Property(e => e.Badge).HasMaxLength(40);
            entity.Property(e => e.DiscoveredBy).HasMaxLength(200);
            entity.Property(e => e.ElectronConfiguration).HasMaxLength(100);
            entity.Property(e => e.Electronegativity).HasColumnType("numeric(18,4)");
            entity.Property(e => e.Rating).HasColumnType("numeric(18,2)");
            
            entity.Property(e => e.AtomicMass).HasColumnType("numeric(18,4)");
            entity.Property(e => e.Density).HasColumnType("numeric(18,4)");
            entity.Property(e => e.MeltingPoint).HasColumnType("numeric(18,4)");
            entity.Property(e => e.BoilingPoint).HasColumnType("numeric(18,4)");
            entity.Property(e => e.PricePerGram).HasColumnType("numeric(18,4)");
            entity.Property(e => e.StockWeightGrams).HasColumnType("numeric(18,4)");
            entity.Property(e => e.ReservedWeightGrams).HasColumnType("numeric(18,4)");
        });

        modelBuilder.Entity<ElementPriceHistory>(entity =>
        {
            entity.HasKey(e => e.Id);
            entity.HasIndex(e => e.ElementSymbol);
            entity.Property(e => e.ElementSymbol).IsRequired().HasMaxLength(10);
            entity.Property(e => e.Price).HasColumnType("numeric(18,4)");
        });

        modelBuilder.Entity<ElementCategory>(entity =>
        {
            entity.HasKey(c => c.Id);
            entity.HasIndex(c => c.Slug).IsUnique();
            entity.Property(c => c.Name).IsRequired().HasMaxLength(100);
            entity.Property(c => c.Slug).IsRequired().HasMaxLength(100);
            entity.Property(c => c.Description).HasMaxLength(500);
        });

        modelBuilder.Entity<StockReservation>(entity =>
        {
            entity.HasKey(r => r.OrderId);
            entity.Property(r => r.ElementSymbol).IsRequired().HasMaxLength(10);
            entity.Property(r => r.Quantity).HasColumnType("numeric(18,4)");
            entity.Property(r => r.Status).IsRequired().HasMaxLength(20);
        });

